; WS2801 LED chain (clock and data); tape word 0 = LED count n, words 1..n = RGB colours; latched, repeated for ever
; Generated by escgen from protocols/ws2801_tx.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: Worldsemi WS2801 datasheet: data sampled on the rising edge of CKI, 24 bits per IC (R, G, B, MSB first), CKI up to 25 MHz, CKI low for 500 us latches the data (600 us here); a 500 kHz clock here: one bit is three events, six instructions
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ H, CLK_KHZ // 1000
.equ Q, CLK_KHZ // 2000
.equ TLATCH, CLK_KHZ * 600 // 1000
.default PIN_CI, 0
.equ P_CI, 1 << PIN_CI
.default PIN_DI, 1
.equ P_DI, 1 << PIN_DI

.own  PIN_CI, CTX
.own  PIN_DI, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_CI | P_DI, 0, P_CI | P_DI ; idle levels
    ADDT  1
packet:
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    MOVI  r2, 0                       ; tape address
    LDT   r3, r2, 0                   ; words in this packet
    ADDI  r2, 1
    CMPI  r3, 0
    JZ    packet                      ; an empty packet: look again
next_word:
    LDT   r0, r2, 0
    SHL   r0, 8                       ; the field's first bit to bit 31
    LDSH  r0                          ; 24 bits, MSB first
    LDLC  24
bit1:
    EMITX P_DI, MSB, P_DI             ; data bit
    ADDT  Q
    EMIT  P_CI, P_CI, P_CI
    ADDT  H
    EMIT  P_CI, 0, P_CI
    ADDT  H - Q
    DJNZ  bit1
    ADDI  r2, 1
    MOVI  r0, 1
    SUB   r3, r0                      ; Z after the last word
    JNZ   next_word
    ADDT  TLATCH                      ; latch: no change, no event
    JMP   packet
